function paintInfo(p){
  if(!p) return null;
  if(p.type==="SOLID") return "solid "+hex(p.color)+" op="+Math.round((p.opacity??1)*100)/100;
  if(p.type==="IMAGE") return "image scale="+p.scaleMode+" ref="+(p.imageRef||"none");
  if(p.type==="GRADIENT_LINEAR") return "linear "+(p.gradientStops||[]).map(s=>hex(s.color)).join("->");
  return p.type;
}

