  t.fontName={family:"DM Sans", style:st(o.weight||"Regular")}; t.fontSize=o.size||14;
  t.fills=[{type:"SOLID", color:hex(o.color||COL.text1)}];
  if(o.op!==undefined) t.opacity=o.op;
  t.lineHeight=o.lh?{value:o.lh, unit:"PIXELS"}:{value:1.3, unit:"PERCENT"};
  if(o.align==="center") t.textAlignHorizontal="CENTER";
  parent.appendChild(t);
  if(o.wrap && o.w){ t.textAutoResize="HEIGHT"; t.resize(o.w, 1); t.x=o.x; t.y=o.y; }
  else {
    t.textAutoResize="WIDTH_AND_HEIGHT";
    if(o.center){ const bw=o.w||parent.width; const bh=o.h||parent.height; t.x=Math.round((bw-t.width)/2); t.y=Math.round((bh-t.height)/2); }
    else { t.x=o.x||0; t.y=o.y||0; }
  }
  return t;
}
function F(parent,name,x,y,w,h,fill,o={}){
  const f=figma.createFrame(); f.name=name; f.x=x; f.y=y; f.resize(w,h);
  f.clipsContent = o.clip!==false; f.layoutMode="NONE";
  if(fill){ f.fills = Array.isArray(fill)? fill : (typeof fill==="string" && fill.startsWith("#")) ? [{type:"SOLID", color:hex(fill)}] : [fill]; }
  if(o.radius!==undefined) f.cornerRadius=o.radius;
  if(o.stroke) f.strokes=[{type:"SOLID", color:hex(o.stroke)}];
  if(o.strokeW) f.strokeWeight=o.strokeW;
  if(o.op!==undefined) f.opacity=o.op;
  parent.appendChild(f); return f;
}
function R(parent,name,x,y,w,h,fill,o={}){
  const r=figma.createRectangle(); r.name=name; r.x=x; r.y=y; r.resize(w,h);
  if(fill){ if(typeof fill==="string" && fill.startsWith("#")) r.fills=[{type:"SOLID", color:hex(fill)}]; else r.fills=[fill]; }
  if(o.radius!==undefined) r.cornerRadius=o.radius;
  if(o.stroke) r.strokes=[{type:"SOLID", color:hex(o.stroke)}];
  if(o.strokeW) r.strokeWeight=o.strokeW;
  if(o.op!==undefined) r.opacity=o.op;
  parent.appendChild(r); return r;
}
function findImageHash(node){
  if("fills" in node && Array.isArray(node.fills)){ for(const p of node.fills){ if(p.type==="IMAGE" && p.imageHash) return p.imageHash; } }
  if(node.children){ for(const c of node.children){ const h=findImageHash(c); if(h) return h; } }
  return null;
}
function recolorAll(node, col){
  (function it(n){
    if("fills" in n && Array.isArray(n.fills)) n.fills = n.fills.map(p=> p.type==="IMAGE"?p:{type:"SOLID", color:hex(col)});
    if("strokes" in n && Array.isArray(n.strokes) && n.strokes.length) n.strokes=[{type:"SOLID", color:hex(col)}];
    (n.children||[]).forEach(it);
  })(node);
}
function cloneMaster(nodeId, name){
  const node = figma.getNodeById(nodeId); if(!node) throw new Error("missing "+nodeId);
  let m = node.type==="COMPONENT" ? node : (node.type==="INSTANCE" ? node.masterComponent : null);
  if(!m) throw new Error("no master for "+nodeId);
  const c = m.clone(); c.name = name; figma.currentPage.appendChild(c); return c;
}
function imgFill(hash){ return {type:"IMAGE", imageHash:hash, scaleMode:"FILL"}; }

