const out = [];
function walk(n, d){
  if(!n) return;
  let info = {name:n.name, type:n.type, id:n.id};
  if("characters" in n) info.text = n.characters;
  if(n.type==="TEXT"){ try{ info.font = JSON.stringify(n.fontName); info.size=n.fontSize; }catch(e){} }
  if("fills" in n && Array.isArray(n.fills)) info.fills = n.fills.map(p=>p.type==="IMAGE"?"IMG:"+(p.imageHash||"none"):p.type).join(",");
  if("children" in n && n.children.length){ info.children = n.children.length; }
  out.push({d, ...info});
  if("children" in n){ for(const c of n.children) walk(c, d+1); }
}
for(const c of page.children){
