function SF(w){ const m={Regular:["Regular"],Medium:["Medium","Regular"],Semi:["SemiBold","Semi Bold","Bold"],Bold:["Bold","SemiBold","Regular"]}; for(const c of (m[w]||["Regular"])){ if(L.has(c)) return c; } return "Regular"; }
