function Rect(p,n,x,y,w,h,fill,r){ const e=figma.createRectangle(); e.name=n; e.resize(w,h); if(r!==undefined) e.cornerRadius=r; if(fill){ if(typeof fill==="string") e.fills=[{type:"SOLID",color:hx(fill)}]; else e.fills=[fill]; } if(p) p.appendChild(e); e.x=x; e.y=y; return e; }
function Box(p,n,x,y,w,h,fill,r,clip){ const e=figma.createFrame(); e.name=n; e.resize(w,h); e.x=x; e.y=y; e.layoutMode="NONE"; if(clip===undefined) clip=false; e.clipsContent=clip; if(fill){ e.fills=[{type:"SOLID",color:hx(fill)}]; } else { e.fills=[]; } if(r!==undefined) e.cornerRadius=r; if(p) p.appendChild(e); return e; }
function Txt(p,n,s,x,y,size,wt,col){ const t=figma.createText(); t.name=n; t.characters=s; t.fontName={family:"DM Sans",style:SF(wt)}; t.fontSize=size; t.fills=[{type:"SOLID",color:hx(col)}]; t.lineHeight={value:Math.round(size*1.35),unit:"PIXELS"}; t.textAutoResize="WIDTH_AND_HEIGHT"; p.appendChild(t); t.x=x; t.y=y; return t; }
function TxtW(p,n,s,x,y,w,size,wt,col){ const t=figma.createText(); t.name=n; t.characters=s; t.fontName={family:"DM Sans",style:SF(wt)}; t.fontSize=size; t.fills=[{type:"SOLID",color:hx(col)}]; t.lineHeight={value:Math.round(size*1.45),unit:"PIXELS"}; t.resize(w,300); t.textAutoResize="HEIGHT"; p.appendChild(t); t.x=x; t.y=y; return t; }
