function SF(w){ const m={Regular:["Regular"],Medium:["Medium","Regular"],Semi:["SemiBold","Semi Bold","Bold"],Bold:["Bold","SemiBold","Regular"]}; for(const c of (m[w]||["Regular"])){ if(L.has(c)) return c; } return "Regular"; }
const C={t1:"#1A1E25",t2:"#5C6470",t3:"#98A0AC",brd:"#E7EAF0",brand:"#0ACF83",star:"#FFB020",surf:"#FFFFFF"};
function hx(h){ const v=parseInt(h.slice(1),16); return {r:((v>>16)&255)/255, g:((v>>8)&255)/255, b:(v&255)/255}; }
function findC(nm){ return page.findOne(c=>c.type==="COMPONENT" && c.name===nm); }
function Txt(p,n,s,x,y,size,wt,col,o={}){
  const t=figma.createText(); t.name=n; t.characters=s; t.fontName={family:"DM Sans",style:SF(wt)}; t.fontSize=size;
  t.fills=[{type:"SOLID",color:hx(col)}];
  t.lineHeight=o.lh?{value:o.lh,unit:"PIXELS"}:{value:Math.round(size*1.4),unit:"PIXELS"};
  if(o.w){ t.resize(o.w,400); t.textAutoResize="HEIGHT"; } else { t.textAutoResize="WIDTH_AND_HEIGHT"; }
  p.appendChild(t); t.x=x; t.y=y; return t;
}
function Rect(p,n,x,y,w,h,fill,r,o={}){
  const e=figma.createRectangle(); e.name=n; e.resize(w,h);
  if(fill) e.fills=[{type:"SOLID",color:hx(fill)}]; else e.fills=[];
  if(r!==undefined) e.cornerRadius=r;
  if(o.stroke) e.strokes=[{type:"SOLID",color:hx(o.stroke)}];
  if(o.sw) e.strokeWeight=o.sw;
  p.appendChild(e); e.x=x; e.y=y; return e;
}
function Box(p,n,x,y,w,h,fill,r,clip){
  const e=figma.createFrame(); e.name=n; e.resize(w,h); e.x=x; e.y=y; e.layoutMode="NONE";
  e.clipsContent=!!clip; e.fills=fill?[{type:"SOLID",color:hx(fill)}]:[];
  if(r!==undefined) e.cornerRadius=r;
  p.appendChild(e); return e;
}
function imgHashOf(master){
  let h=null;
  (function walk(n){ if(h) return; if("fills" in n && Array.isArray(n.fills)){ for(const p of n.fills){ if(p.type==="IMAGE"&&p.imageHash){ h=p.imageHash; return; } } } if("children" in n){ n.children.forEach(walk); } })(master);
  return h;
}
function imgFill(hash){ return {type:"IMAGE", imageHash:hash, scaleMode:"FILL"}; }
function setIcon(holder, icoName, size, sx, sy, color){
  const icon = findC(icoName).createInstance(); icon.resize(size,size); if(color) icon.fills=[{type:"SOLID",color:hx(color)}];
  holder.appendChild(icon); icon.x=sx; icon.y=sy; return icon;
}

