function SF(w){ const m={Regular:["Regular"],Medium:["Medium","Regular"],SemiBold:["SemiBold","Semi Bold","Bold"],Bold:["Bold","SemiBold","Regular"]}; for(const c of (m[w]||["Regular"])){ if(L.has(c)) return c; } return "Regular"; }
function hx(h){ const v=parseInt(h.slice(1),16); return {r:((v>>16)&255)/255,g:((v>>8)&255)/255,b:(v&255)/255}; }
// T(parent, name, str, x, y, w, size, weight, color, lh, align)  lh>0 fixed height center; lh===-1 auto height paragraph
function T(p,n,s,x,y,w,size,weight,color,lh,align){
  const t=figma.createText(); t.name=n; t.characters=s;
  t.fontName={family:"DM Sans",style:SF(weight)}; t.fontSize=size;
  t.fills=[{type:"SOLID",color:hx(color)}];
  p.appendChild(t);
  if(w>0){
    if(lh===-1){ t.resize(w, Math.ceil(size*1.4)); t.textAutoResize="HEIGHT"; t.x=x; t.y=y; }
    else { const h = (typeof lh==="number"&&lh>0)?lh:Math.ceil(size*1.3); t.textAutoResize="NONE"; t.resize(w,h); t.x=x; t.y=y; t.textAlignVertical="CENTER"; }
  } else { t.textAutoResize="WIDTH_AND_HEIGHT"; t.x=x; t.y=y; }
  if(align==="right") t.textAlignHorizontal="RIGHT";
  return t;
}
function R(p,n,x,y,w,h,fill,o){
  const r=figma.createRectangle(); r.name=n; r.x=x; r.y=y; r.resize(w,h);
  if(fill==="none") r.fills=[]; else if(typeof fill==="string"&&fill[0]==="#") r.fills=[{type:"SOLID",color:hx(fill)}]; else if(fill) r.fills=[fill];
  if(o){ if(o.r!==undefined) r.cornerRadius=o.r; if(o.stroke) r.strokes=[{type:"SOLID",color:hx(o.stroke)}]; if(o.sw) r.strokeWeight=o.sw; if(o.op!==undefined) r.opacity=o.op; }
  p.appendChild(r); return r;
}
function F(p,n,x,y,w,h,fill,o){
  const f=figma.createFrame(); f.name=n; f.x=x; f.y=y; f.resize(w,h); f.clipsContent=(o&&o.clip===false)?false:true; f.layoutMode="NONE";
  if(fill==="none") f.fills=[]; else if(typeof fill==="string"&&fill[0]==="#") f.fills=[{type:"SOLID",color:hx(fill)}]; else if(fill) f.fills=[fill];
  if(o){ if(o.r!==undefined) f.cornerRadius=o.r; if(o.stroke) f.strokes=[{type:"SOLID",color:hx(o.stroke)}]; if(o.sw) f.strokeWeight=o.sw; }
  p.appendChild(f); return f;
}
function img(h){ return {type:"IMAGE", imageHash:h, scaleMode:"FILL"}; }
function findImg(n){
  if("fills" in n && Array.isArray(n.fills)){ for(const p of n.fills){ if(p.type==="IMAGE"&&p.imageHash) return p.imageHash; } }
  if("children" in n){ for(const c of n.children){ const h=findImg(c); if(h) return h; } }
  return null;
}
