function IC(nm){ return page.findOne(c=>c.type==="COMPONENT" && c.name===nm); }
function iconInst(nm,size,x,y,parent,color){
  const i=IC(nm).createInstance(); i.name=nm; i.resize(size,size); i.x=x; i.y=y; parent.appendChild(i);
  if(color){ const col=hx(color); i.children.forEach(ch=>{ if("fills" in ch && Array.isArray(ch.fills) && ch.fills.length){ ch.fills=ch.fills.map(p=>p.type==="IMAGE"?p:{type:"SOLID",color:col}); } }); }
