for(const c of page.children){ if(c.name && c.name.startsWith("DIAGM:")){ old=c; break; } }
if(old) old.remove();
const f = figma.createFrame();
f.name = "DIAGM:: " + lines.join(" § ");
f.resize(10,10);
f.x = -4000; f.y = -4000;
page.appendChild(f);
"baked";

