function fillsInfo(n){ if(!("fills" in n)) return ""; try{ return n.fills.map(f=>hexOf(f)+(f.type==="IMAGE"?"@"+(f.imageHash||"none").slice(0,6):"")).join(","); }catch(e){ return "ERR"; } }
function firstChildWithFill(n){ if(!n) return null; if("fills" in n && Array.isArray(n.fills) && n.fills.length && n.fills[0].type!=="IMAGE") ; let res=null; (function w(x){ if(res) return; if("fills" in x && Array.isArray(x.fills) && x.fills.length){ res=x; return; } if(x.children){ for(const c of x.children){ if(res) return; w(c);} } })(n); return res; }
